sql.if:
AND(
    t1.notifc_type_id ILIKE CONCAT('%', #{searchTypeKeyword}, '%'
) OR
    t1.notifc_type_nm ILIKE CONCAT('%', #{searchTypeKeyword}, '%')
)

mapper.select:
SELECT EXISTS (  /* SQL_ID: NotifcTypeMapper.isNotifcTypeIdExist */
    SELECT 1
    FROM dtmeta.tb_portal_notifctype
    WHERE notifc_type_id = #{notifcTypeId}
)

mapper.insert:
INSERT
INTO dtmeta.tb_portal_notifctype (  /* SQL_ID: NotifcTypeMapper.insertNotifcType */
    notifc_type_id
    , notifc_type_nm
    , notifc_use_yn
    , notifc_type_desc
    , notifc_msg_rstrtn_len
    , notifc_msg_tmplt
    , notifc_link_tmplt_url
    , notifc_type_sort_odrg            
    , notifc_type_regr_id
    , notifc_type_regr_nm
    , notifc_type_reg_dt
    , notifc_type_amdr_id
    , notifc_type_amdr_nm
    , notifc_type_amd_dt
)
VALUES (
    #{notifcTypeId}
    , #{notifcTypeNm}
    , #{notifcUseYn}
    , #{notifcTypeDesc}
    , #{notifcMsgRstrtnLen}
    , #{notifcMsgTmplt}
    , #{notifcLinkTmpltUrl}
    , #{notifcTypeSortOdrg}            
    , #{notifcTypeRegrId}
    , #{notifcTypeRegrNm}
    , current_timestamp
    , #{notifcTypeAmdrId}
    , #{notifcTypeAmdrNm}
    , current_timestamp
)

mapper.update:
UPDATE dtmeta.tb_portal_notifctype   /* SQL_ID: NotifcTypeMapper.updateNotifcType */
SET
    notifc_type_nm = #{notifcTypeNm}
    , notifc_use_yn = #{notifcUseYn}
    , notifc_type_desc = #{notifcTypeDesc}
    , notifc_msg_rstrtn_len = #{notifcMsgRstrtnLen}
    , notifc_msg_tmplt = #{notifcMsgTmplt}
    , notifc_link_tmplt_url = #{notifcLinkTmpltUrl}
    , notifc_type_sort_odrg = #{notifcTypeSortOdrg}            
    , notifc_type_amdr_id = #{notifcTypeAmdrId}
    , notifc_type_amdr_nm = #{notifcTypeAmdrNm}
    , notifc_type_amd_dt = current_timestamp
WHERE notifc_type_id = #{notifcTypeId}

mapper.delete:
DELETE   /* SQL_ID: NotifcTypeMapper.deleteNotifcType */
FROM dtmeta.tb_portal_notifctype
WHERE notifc_type_id = #{notifcTypeId}

mapper.select:
SELECT EXISTS (  /* SQL_ID: NotifcTypeMapper.isNotifcTypeIdExistInTarget */
    SELECT 1
    FROM dtmeta.tb_portal_notifctarget
    WHERE notifc_type_id = #{notifcTypeId}
)
